export class BadRequestError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'BadRequestError';
  }
}

/** Reads untyped request input (JSON body or query string) into typed values. */
export class RequestReader {
  private readonly source: Record<string, unknown>;

  constructor(input: unknown) {
    if (input === undefined || input === null) {
      this.source = {};
    } else if (typeof input === 'object' && !Array.isArray(input)) {
      this.source = input as Record<string, unknown>;
    } else {
      throw new BadRequestError('Request input must be a JSON object');
    }
  }

  requiredString(key: string): string {
    const value = this.optionalString(key);
    if (value === undefined) {
      throw new BadRequestError(`'${key}' is required`);
    }
    return value;
  }

  optionalString(key: string): string | undefined {
    const value = this.source[key];
    if (value === undefined || value === null) {
      return undefined;
    }
    if (typeof value !== 'string') {
      throw new BadRequestError(`'${key}' must be a string`);
    }
    return value;
  }
}

